// Included after the Vector/Particle declarations generated by oriented.py.
inline Vector quarter_turn(Vector u,int sector) {
    switch(sector) {
        case 1: return {-u.y,u.x,u.z};
        case 2: return {-u.x,-u.y,u.z};
        case 3: return {u.y,-u.x,u.z};
        default: return u;
    }
}
inline Vector charge_partner(Vector u) { return {u.x,-u.y,-u.z}; }
inline Vector final_basis(Vector u,int axis) {
    if(axis==0) return {u.y,u.z,u.x};
    if(axis==1) return {u.z,u.x,u.y};
    return u;
}
inline Particle canonical_particle(Vector physical,double radius,double impulse,int hits) {
    return {radius*std::hypot(physical.x,physical.y),radius*physical.z-impulse,
            hits,radius*physical.x,radius*physical.y};
}
inline double average_inverse_energy(double qperp,double z0,double z1,double radius) {
    const double perp=qperp/radius, a=z0/radius,b=z1/radius;
    const double h2=1.+perp*perp;
    const double denom=std::sqrt(h2+a*a)+std::sqrt(h2+b*b);
    const double x=(b-a)/denom, x2=x*x;
    if(x2<1e-3) return (2./denom)*(1.+x2*(1./3.+x2*(.2+x2/7.)));
    if(x2>.64) {
        const double h=std::sqrt(h2);
        return (std::asinh(b/h)-std::asinh(a/h))/(b-a);
    }
    return 2.*std::atanh(x)/(b-a);
}
inline void rotate_gyro(Particle& p,double phase) {
    // A positive charge in +Bz rotates clockwise when viewed from +z.
    const double c=std::cos(phase),s=std::sin(phase),x=p.qx;
    p.qx=c*x+s*p.qy;
    p.qy=c*p.qy-s*x;
}
inline double mid_step_energy(const Particle& p,double a,double impulse) {
    const double pt=p.qperp/a,pz=(p.qz+impulse)/a;
    return std::sqrt(1.+pt*pt+pz*pz);
}
